const body = $json.body || $json;
const value = body.entry?.[0]?.changes?.[0]?.value || body.value || body;
const metaMessage = value.messages?.[0] || body.messages?.[0] || {};
const contact = value.contacts?.[0] || body.contacts?.[0] || {};
const message = metaMessage.text?.body || body.message || body.text || body.body || '';
const phone = metaMessage.from || body.phone || body.from || '';
const name = body.customerName || contact.profile?.name || 'Lead WhatsApp';
return [{
  json: {
    workspaceId: $env.NOWCRM_WORKSPACE_ID,
    provider: 'meta',
    phone,
    customerName: name,
    message,
    externalConversationId: value.metadata?.phone_number_id || phone,
    externalMessageId: metaMessage.id || body.messageId || body.id,
    timestamp: metaMessage.timestamp ? new Date(Number(metaMessage.timestamp) * 1000).toISOString() : (body.timestamp || new Date().toISOString()),
    metadata: {
      source: 'n8n_meta_cloud_api',
      rawProvider: 'meta',
      phoneNumberId: value.metadata?.phone_number_id
    }
  }
}];
